import {routeCards,mapFocusSummary} from './mobile-workspace.mjs';
import {advisoryButton} from './corridor-advisory.mjs';
import {DEPARTURE,rankRoutes,money,dateLabel,referenceRoute} from './model.mjs';
import {routeGroups,priorityLabel,mapReference,columnSortState} from './planner-model.mjs';
import {scenarioLabView} from './scenario-lab.mjs';
import {mapLegend,mapRoutePicker} from './route-map.mjs';
import {journeyView} from './analysis-views.mjs';
import {journeyPlayer} from './journey-preview.mjs';
import {statusPill} from './planning-views.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const costChange=n=>`${n>0?'+':n<0?'−':''}${money(Math.abs(n))}`;
const modeIcon=mode=>({ocean:'ship',rail:'train',multimodal:'mixed',air:'plane'})[mode];
export function tableRows(settings,compare,icon) {
 const best=rankRoutes(settings).find(r=>r.feasible),base=referenceRoute(settings);
 return routeGroups(settings).map(group=>`<tbody aria-label="${group.label}"><tr class="route-group-heading"><th colspan="8" scope="rowgroup" id="group-${group.id}" tabindex="-1"><span class="group-indicator ${group.id}"></span>${group.label}<b>${group.routes.length}</b><small>${group.id==='eligible'?'Meets all three planning limits':'Fails one or more limits'}</small></th></tr>${group.routes.map(r=>`<tr class="${r.id===settings.selected?'selected-row':''} ${r.feasible?'is-eligible':'is-outside'}" data-route="${r.id}"><td class="check-cell"><input type="checkbox" data-compare="${r.id}" data-focus="compare-${r.id}" aria-label="Add ${esc(r.name)} to comparison" ${compare.has(r.id)?'checked':''}></td><td><button class="route-name" data-action="select" data-value="${r.id}" data-focus="route-${r.id}" ${r.id===settings.selected?'aria-current="true"':''}><span class="table-mode">${icon(modeIcon(r.mode),18)}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.service)}${r.id==='seaair'?'<span class="advisory-route-label">Hormuz notice</span>':''}${r.id===best?.id?'<span class="best-fit">Recommended</span>':''}${r.id===settings.selected?'<span class="active-route-label">On map</span>':''}</small></span></button></td><td class="numeric cost-cell">${money(r.cost)}<small class="cost-delta">${r.id===settings.baseline?'Baseline':`${costChange(r.cost-base.cost)} vs base`}</small></td><td class="numeric">${r.days}<span class="unit"> days</span></td><td class="numeric">${dateLabel(r.arrival)}<small class="arrival-delta ${r.buffer<0?'caution':'muted'}">${r.buffer<0?`${-r.buffer}d late`:r.buffer===0?'On deadline':`${r.buffer}d to spare`}</small></td><td class="numeric">${r.co2.toFixed(1)} <span class="unit">t</span><small>±${r.uncertainty}%</small></td><td>${statusPill(r,icon)}</td><td class="row-arrow"><button class="icon-button baseline-pin ${r.id===settings.baseline?'pinned':''}" data-action="pin-baseline" data-value="${r.id}" data-focus="pin-${r.id}" aria-label="Use ${esc(r.name)} as baseline" aria-pressed="${r.id===settings.baseline}">${icon('pin',15)}</button></td></tr>`).join('')}${group.routes.length?'':`<tr class="empty-group"><td colspan="8">No routes in this group. ${group.id==='eligible'?'<button class="text-button" data-action="constraints">Review planning limits</button>':''}</td></tr>`}</tbody>`).join('');
}
export function plannerView(state,helpers) {
 const {settings,compare,chartMode,mapWide,showAllRoutes,activeMapLocation,activeLeg,costDetailsOpen,mapDetails,showRecorded,compact=false}=state;
 const {icon,map,mapLocationCard,tradeoffChart}=helpers;
 const r=rankRoutes(settings).find(r=>r.id===settings.selected),ref=mapReference(settings),base=referenceRoute(settings);
 const sortHeader=(key,label)=>{const state=columnSortState(settings,key);return `<th class="numeric sortable-header" aria-sort="${state}"><button data-action="sort" data-value="${key}" data-focus="sort-${key}" aria-label="${label}: ${state==='none'?'sort':state==='ascending'?'ascending; sort descending':'descending; sort ascending'}"><span>${label}</span>${icon(state==='none'?'sort':state==='ascending'?'sort-up':'sort-down',15)}</button></th>`;};
 const limit=(label,value,violation,ico)=>`<button class="constraint-chip ${violation?'is-violated':''}" data-action="constraints" data-value="${ico==='euro'?'budget':ico==='calendar'?'deadline':'emissions'}" aria-label="Edit ${label.toLowerCase()} limit">${icon(ico,15)}<span>${label}</span><strong>${value}</strong>${icon('down',12)}</button>`;
 return `<section class="shipment-workspace panel" aria-label="Shipment and planning limits"><div class="shipment-workspace-heading"><div><span class="overline">SHIPMENT SHP-2026-0842</span><h1>Shanghai <span>→</span> Rotterdam</h1><p>Industrial components · 4 × 40′ HC · 72 t · Ready ${dateLabel(DEPARTURE)}</p></div><div class="heading-actions"><button class="icon-button" data-action="reset-settings" aria-label="Reset assumptions" title="Reset assumptions">${icon('reset',17)}</button><button class="button primary" data-action="save" ${r.feasible?'':'disabled title="Choose a route within limits to save"'}>${icon('bookmark',15)} Save scenario</button></div></div><div class="shipment-constraints"><span class="constraint-label">PLANNING LIMITS</span>${limit('Budget',money(settings.budget),r.cost>settings.budget,'euro')}${limit('Deadline',dateLabel(settings.deadline),r.buffer<0,'calendar')}${limit('CO₂e',`${settings.emissions} t`,r.co2>settings.emissions,'leaf')}</div></section><nav class="mobile-workspace-jumps" aria-label="Planner sections"><button data-action="planner-jump" data-value="overview">${icon('route',16)}Overview</button><button data-action="planner-jump" data-value="routes">${icon('grid',16)}Routes <span>6</span></button><button data-action="planner-jump" data-value="lab">${icon('sliders',16)}Scenario lab</button></nav><div class="planner-grid ${mapWide&&chartMode==='map'?'map-wide':''}"><section class="map-panel panel"><header class="overview-header"><div class="view-switch" aria-label="Overview view">${[['map','Map'],['tradeoffs','Trade-offs'],['journey','Journey']].map(([id,label])=>`<button data-action="chart-mode" data-value="${id}" data-focus="${id}-tab" aria-pressed="${chartMode===id}">${label}</button>`).join('')}</div></header><div class="map-stage map-mode-${chartMode}" aria-label="${chartMode==='map'?'Route map from Shanghai to Rotterdam':chartMode==='journey'?'Planned delivery stages':'Cost and transit comparison'}">${chartMode==='map'?`${map(r,ref.id)}${compact?'':mapLegend(r,ref.id,icon,ref.label,showRecorded)}<div class="map-overlay-actions"><button class="map-tool" data-action="layers" data-focus="map-layers" aria-label="${showAllRoutes?'Hide route network':'Show route network'}" aria-expanded="${showAllRoutes}">${icon('grid',16)}<span>Routes</span></button><button class="map-tool" data-action="map-details" title="Show or hide country details" aria-label="Toggle geographic details" aria-pressed="${mapDetails}">${icon('layers',16)}</button><button class="map-tool map-expand" data-action="map-wide" data-focus="map-wide" aria-label="${mapWide?(compact?'Close full-screen map':'Return to split view'):'Expand route map'}" aria-expanded="${mapWide}">${icon(mapWide?'close':'expand',16)}<span>${mapWide?(compact?'Close map':'Split view'):'Expand'}</span></button></div>${showAllRoutes?mapRoutePicker(r.id,icon):''}${mapLocationCard(r)}<div class="map-preview-caption" data-map-preview-caption role="status" hidden></div><div class="map-controls"><button data-action="zoom-out" aria-label="Zoom out">${icon('minus',16)}</button><output data-map-scale aria-label="Map zoom" aria-live="off">100%</output><button data-action="zoom-in" aria-label="Zoom in">${icon('plus',16)}</button><button class="map-fit" data-action="zoom-fit" aria-label="Fit route map">${icon('expand',15)}<span>Fit</span></button></div><span id="map-navigation-help" class="sr-only">Scroll to zoom. Drag to move when zoomed. On touch screens, expand the map to drag and pinch; swipe the embedded map to scroll the page. Focus map: plus or minus zoom, arrows pan, 0 fits.</span>`:chartMode==='journey'?`<div class="journey-experience">${journeyPlayer(icon)}${journeyView(r,settings,activeLeg,icon)}</div>`:`${tradeoffChart()}<div id="route-tooltip" class="chart-tooltip" role="tooltip" hidden></div>`}</div>${chartMode==='map'?`${compact?mapLegend(r,ref.id,icon,ref.label,showRecorded):''}${compact&&mapWide?mapFocusSummary(r,icon):''}<div class="map-location-outside">${mapLocationCard(r)}</div>`:''}</section>${scenarioLabView(settings,icon,costDetailsOpen)}</div><section class="scenario-section" aria-labelledby="scenarios-heading"><header class="section-heading"><div><h2 id="scenarios-heading">Route options <span class="count">6</span></h2><p class="baseline-caption">Baseline: <strong>${esc(base.short)}</strong>${settings.baseline!=='cape'?'<button data-action="reset-baseline">Reset</button>':''}</p></div><div class="route-section-actions">${advisoryButton(icon)}<button class="button outline export-routes" data-action="export">${icon('download',15)} Export CSV</button></div></header><div class="scenario-controls"><div class="segmented" aria-label="Route priorities">${[['balanced','Balanced'],['cost','Lowest cost'],['time','Fastest'],['carbon','Lower emissions']].map(([id,label])=>`<button data-action="priority" data-value="${id}" aria-pressed="${settings.sort==='score'&&settings.priority===id}">${label}</button>`).join('')}</div><button class="text-button sort-explanation" data-action="explain-ranking">Within limits first · ${priorityLabel(settings)} ${icon('info',14)}</button></div>${compact?routeCards(settings,compare,icon):`<div class="table-panel panel"><p class="table-scroll-hint">Swipe to compare all columns. Check boxes add routes to a comparison.</p><div class="table-scroll"><table class="routes-table"><colgroup><col style="width:44px"><col style="width:290px"><col style="width:140px"><col style="width:90px"><col style="width:115px"><col style="width:95px"><col style="width:160px"><col style="width:55px"></colgroup><thead><tr><th class="check-cell"><span title="Select up to three routes to compare">${icon('compare',16)}<span class="sr-only">Comparison selection</span></span></th><th>Route / service</th>${sortHeader('cost','Logistics cost')}${sortHeader('days','Transit')}${sortHeader('arrival','Arrival')}${sortHeader('co2','CO₂e')}<th>Planning status</th><th><span class="sr-only">Pin baseline</span></th></tr></thead>${tableRows(settings,compare,icon)}</table></div><footer class="table-caption"><span>6 routes · All amounts in EUR · Estimates, not live quotes.</span><span>Check boxes compare · Pin sets baseline</span></footer></div>`}<div class="compare-bar ${compare.size?'is-visible':''}"><span>${icon('compare',18)}<strong>${compare.size} of 3 selected</strong><span class="compare-hint">Same shipment. Same assumptions.</span></span><div><button class="text-button" data-action="clear-compare">Clear</button><button class="button primary" data-action="compare" ${compare.size<2?'disabled':''}>Compare selected ${icon('arrow',15)}</button></div></div></section>`;
}
